function notify(message){toast.textContent=message;toast.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toast.classList.remove('show'),2400)}
function productAsset(i){return ['pampers','huggies','babysec','mamypoko'][i]}
function productCards(){return products.map((p,i)=>`<article class="product-card"><button class="favorite" type="button" aria-label="Favoritar ${p.name}">♡</button><div class="product-image approved-product-stage"><img class="approved-product" src="assets/approved/${productAsset(i)}-approved.png" alt="Embalagem ${p.name} aprovada no acervo"></div><div class="product-body"><span class="badge">${i===2?'Doação':'Disponível'}</span><h3>${p.name}</h3><p>${p.detail}</p><div class="price">${i===2?'Grátis':p.price}</div><div class="meta"><span>★ 4,9</span><span>${p.distance}</span></div><a class="button secondary block small" href="#/site/detail">Ver detalhes</a></div></article>`).join('')}
function siteHome(){return `<section class="hero"><div><span class="eyebrow">● Economia circular que transforma</span><h1>Pequenas escolhas,<br><span>grandes mudanças.</span></h1><p>Compre, troque ou doe fraldas fechadas com segurança, economia e impacto positivo.</p><div class="hero-actions"><a class="button primary" href="#/site/search">Explorar anúncios →</a><a class="button secondary" href="#/site/publish">Publicar anúncio</a></div><div class="trust-row"><span>Perfis verificados</span><span>Pagamento protegido</span><span>Impacto mensurável</span></div></div><div class="hero-visual" role="img" aria-label="Planeta, folhas e fraldas representando economia circular"><div class="floating-card one"><strong>7.420</strong> pacotes reaproveitados</div><div class="floating-card two"><strong>124</strong> famílias beneficiadas</div><div class="earth"></div><div class="diaper-stack"></div><div class="leaf"></div></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">Como funciona</span><h2>Uma jornada simples e segura</h2></div><p>Do anúncio à entrega, cada etapa é acompanhada.</p></div><div class="feature-grid"><article class="feature-card"><div class="icon">⌕</div><h3>Encontre</h3><p>Busque por marca, tamanho, preço e distância.</p></article><article class="feature-card"><div class="icon">↔</div><h3>Negocie</h3><p>Compre, troque ou doe pelo chat protegido.</p></article><article class="feature-card"><div class="icon">▣</div><h3>Pague</h3><p>Use Pix, cartão, boleto ou saldo FraldaCycle.</p></article><article class="feature-card"><div class="icon">⌖</div><h3>Receba</h3><p>Acompanhe a entrega ou combine a retirada.</p></article></div></section><div class="marketplace"><section class="section"><div class="section-head"><div><span class="eyebrow">Perto de você</span><h2>Anúncios em destaque</h2></div><a class="button ghost" href="#/site/search">Ver todos →</a></div><div class="filters"><button class="chip active">Todos</button><button class="chip">Venda</button><button class="chip">Troca</button><button class="chip">Doação</button></div><div class="product-grid">${productCards()}</div></section></div><section class="section impact"><div class="impact-graphic"><div><span class="eyebrow" style="color:#fff">Impacto coletivo</span><div class="big">5.080 kg</div><p>de CO₂ evitados por escolhas mais conscientes.</p></div><strong>Juntos por um futuro mais leve.</strong></div><div><span class="eyebrow">Transparência</span><h2>Veja a diferença que a comunidade já está fazendo.</h2><p class="muted">Indicadores demonstrativos classificados como simulados, com período e atualização visíveis.</p><div class="stat-grid"><article class="stat-card"><small>Pacotes reaproveitados · Simulado</small><strong>7.420</strong><span>Atualizado hoje</span></article><article class="stat-card"><small>Economia gerada · Simulado</small><strong>R$ 18.650</strong><span>Período mensal</span></article><article class="stat-card"><small>Resíduos evitados · Simulado</small><strong>2.120 kg</strong><span>Período acumulado</span></article><article class="stat-card"><small>Famílias beneficiadas · Simulado</small><strong>124</strong><span>Período acumulado</span></article></div></div></section>`}
function siteSearch(){return `<section class="section"><div class="section-head"><div><span class="eyebrow">Marketplace</span><h1>Encontre o que sua família precisa</h1></div><a class="button primary" href="#/site/publish">+ Publicar anúncio</a></div><div class="panel"><div class="form-row"><div class="form-group"><label for="q">Buscar</label><input class="input" id="q" placeholder="Marca, tamanho ou categoria"></div><div class="form-group"><label for="city">Localização</label><select class="input" id="city"><option>Belo Horizonte, MG</option><option>Contagem, MG</option></select></div></div><div class="filters"><button class="chip active">Até 5 km</button><button class="chip">Tamanho M</button><button class="chip">Venda</button><button class="chip">Entrega disponível</button><button class="chip">Mais recentes</button></div></div><div class="section-head"><h2>128 resultados</h2><span class="muted">Dados simulados</span></div><div class="product-grid">${productCards()}</div>${resultsMap()}</section>`}
function siteFavorites(){return `<section class="section" id="site-favorites"><div class="section-head"><div><span class="eyebrow">Itens salvos</span><h1>Seus favoritos</h1><p class="muted">Acompanhe anúncios e encontre rapidamente o que você guardou.</p></div><div class="hero-actions"><a class="button secondary" href="#/site/search">Buscar produtos</a><button class="button ghost" id="site-favorites-clear" type="button">Limpar favoritos</button></div></div><div class="segmented favorites-tabs" role="tablist"><button class="active" type="button" role="tab" aria-selected="true">Anúncios (3)</button><button type="button" role="tab" aria-selected="false">Buscas salvas (1)</button></div><div id="site-favorites-content" aria-live="polite"><div class="ui-state loading-state" role="status"><div class="skeleton-stack"><i></i><i></i><i></i></div><p>Carregando seus favoritos...</p></div></div></section>`}
function resultsMap(){return `<section class="results-map-section" aria-labelledby="map-title"><div class="results-map-head"><div><span class="eyebrow">Visualização no mapa</span><h2 id="map-title">Itens encontrados próximos a você</h2></div><span class="muted">4 de 128 resultados visíveis · Simulado</span></div><div class="results-map" role="region" aria-label="Mapa demonstrativo de Belo Horizonte com quatro anúncios encontrados"><button class="map-marker m1 active" data-map-product="0" aria-label="Pampers Confort, 0,8 km"><span>R$45</span></button><button class="map-marker m2" data-map-product="1" aria-label="Huggies Supreme, 1,2 km"><span>R$40</span></button><button class="map-marker m3" data-map-product="2" aria-label="Babysec Premium, 1,4 km"><span>Doar</span></button><button class="map-marker m4" data-map-product="3" aria-label="MamyPoko Fralda-Calça, 1,6 km"><span>R$38</span></button><div class="map-label">Belo Horizonte, MG · raio de 5 km</div><div class="map-preview" id="map-preview"><strong>Pampers Confort</strong><small>M · 50 unidades · 0,8 km</small><a class="button secondary block small" href="#/site/detail">Ver detalhes</a></div></div></section>`}
