function siteSeller(){const sellerProducts=[products[0],products[1],products[3]];return `<section class="section seller-public"><a class="button ghost" href="#/site/detail">← Voltar ao anúncio</a><section class="panel seller-hero"><div class="seller-identity"><div class="avatar seller-avatar">JS</div><div><span class="badge success">✓ Perfil verificado</span><h1>Juliana Silva</h1><p>Membro desde mar/2023 · Belo Horizonte, MG</p><div class="seller-rating"><strong>4,9 ★</strong><span>36 avaliações</span></div></div></div><div class="stat-grid compact seller-stats"><article class="stat-card"><strong>48</strong><small>Anúncios</small></article><article class="stat-card"><strong>36</strong><small>Vendas</small></article><article class="stat-card"><strong>12</strong><small>Trocas</small></article><article class="stat-card"><strong>18</strong><small>Doações</small></article></div></section><div class="dashboard-grid seller-grid"><section class="panel"><span class="eyebrow">Sobre</span><h2>Uma família que acredita na economia circular</h2><p>Mãe de dois pequenos. Compartilho produtos infantis bem cuidados para ajudar outras famílias e reduzir desperdícios.</p><div class="notice"><strong>Segurança e privacidade</strong><br>Dados pessoais e endereço exato só são compartilhados quando necessários em uma negociação confirmada.</div><h3>Indicadores de confiança</h3><div class="phone-list"><article class="phone-card"><span class="status-icon">✓</span><div><strong>Identidade verificada</strong><p>E-mail e telefone confirmados.</p></div></article><article class="phone-card"><span class="status-icon">✓</span><div><strong>Resposta rápida</strong><p>Responde normalmente em até 15 minutos.</p></div></article><article class="phone-card"><span class="status-icon">✓</span><div><strong>Ótimo histórico</strong><p>98% das negociações concluídas.</p></div></article></div></section><section class="panel"><div class="section-head"><div><span class="eyebrow">Avaliações recebidas</span><h2>Reputação na comunidade</h2></div><span class="badge">4,9 de 5</span></div><div class="phone-list"><article class="phone-card"><div class="avatar">MF</div><div><strong>Maria Fernanda · ★★★★★</strong><p>Produto conforme o anúncio e retirada muito rápida.</p><small>Compra · 10/07/2026</small></div></article><article class="phone-card"><div class="avatar">AP</div><div><strong>Ana Paula · ★★★★★</strong><p>Comunicação clara e pacote perfeitamente fechado.</p><small>Troca · 02/07/2026</small></div></article><article class="phone-card"><div class="avatar">RC</div><div><strong>Rafael Costa · ★★★★☆</strong><p>Experiência segura e negociação tranquila.</p><small>Compra · 25/06/2026</small></div></article></div></section></div><section class="panel"><div class="section-head"><div><span class="eyebrow">Anúncios ativos</span><h2>Produtos de Juliana</h2></div><span class="badge">${sellerProducts.length} anúncios</span></div><div class="product-grid">${sellerProducts.map(product=>productCard(product)).join('')}</div></section></section>`}
function siteLogin(){return `<section class="auth-layout"><div class="auth-art"><div><span class="eyebrow" style="color:#fff">Bem-vindo(a)</span><h1>Economia circular para famílias e para o planeta.</h1></div><div class="earth" style="width:180px;height:180px;align-self:center"></div><p>Cada atitude importa.</p></div><form class="auth-form" data-demo-form><h1>Entrar</h1><p class="muted">Acesse sua conta para continuar.</p><div class="form-group"><label for="email">E-mail ou telefone</label><input class="input" id="email" required placeholder="seu@email.com"></div><div class="form-group"><label for="password">Senha</label><input class="input" id="password" type="password" required placeholder="Digite sua senha"></div><a href="#/site/login" class="eyebrow">Esqueci minha senha</a><button class="button primary block" type="submit">Entrar</button><div class="divider">ou continue com</div><div class="social-row"><button type="button" class="button secondary">G Google</button><button type="button" class="button secondary">● Apple</button></div><p class="muted" style="text-align:center">Ainda não tem conta? <a class="eyebrow" href="#/site/publish">Criar conta</a></p></form></section>`}
function sitePublish(){const labels=['Tipo','Produto','Fotos','Condição','Preço','Entrega','Localização','Revisão'];return `<section class="section site-publish-flow"><div class="section-head"><div><span class="eyebrow">Publicar anúncio</span><h1 id="site-publish-title">Novo anúncio</h1><p id="site-publish-subtitle">Etapa 1 de 8 · Tipo de negociação</p></div><span class="badge" id="site-publish-draft">Rascunho salvo</span></div><div class="publish-progress" aria-label="Progresso da publicação">${labels.map((label,index)=>`<button type="button" class="${index===0?'active':''}" data-site-publish-step="${index+1}"><span>${index+1}</span><small>${label}</small></button>`).join('')}</div><div class="site-publish-layout"><aside class="panel publish-guidance"><span class="eyebrow">Publicação segura</span><h2>Publique de forma clara e confiável</h2><p>Preencha cada etapa. Seu rascunho fica salvo durante toda a jornada.</p><div class="notice">Fotos nítidas, informações verdadeiras e localização aproximada aumentam a confiança.</div><ol>${labels.map(label=>`<li>${label}</li>`).join('')}</ol></aside><section class="panel" id="site-publish-content" data-step="1" aria-live="polite"></section></div></section>`}
function siteImpact(){const institutions=[['Instituto Primeiros Passos','Belo Horizonte','328 famílias','Ativa'],['Rede Mães de Contagem','Contagem','214 famílias','Ativa'],['Casa Acolher','Santa Luzia','176 famílias','Ativa'],['Projeto Infância Circular','Ribeirão das Neves','124 famílias','Expansão']];return `<section class="section impact-dashboard"><div class="section-head"><div><span class="eyebrow">Impacto socioambiental</span><h1>Resultados que transformam territórios</h1><p>Indicadores demonstrativos com período, geografia e origem identificados.</p></div><button class="button secondary" id="impact-methodology">Metodologia e fontes</button></div><section class="panel"><div class="form-row"><div class="form-group"><label>Período</label><select class="input" id="impact-period"><option value="12">Últimos 12 meses</option><option value="6">Últimos 6 meses</option><option value="1">Mês atual</option><option value="all">Desde o início</option></select></div><div class="form-group"><label>Região</label><select class="input" id="impact-region"><option value="all">Todas as regiões</option><option value="bh">Belo Horizonte</option><option value="contagem">Contagem</option><option value="santa-luzia">Santa Luzia</option><option value="ribeirao">Ribeirão das Neves</option></select></div><div class="form-group"><label>Indicador</label><select class="input" id="impact-indicator"><option>Visão consolidada</option><option>Resíduos</option><option>Emissões</option><option>Famílias</option><option>Economia</option></select></div></div><small class="muted">Natureza: valores simulados para demonstração · atualização: hoje, 06:00 · fonte: Data Warehouse FraldaCycle</small></section><div class="stat-grid admin"><article class="stat-card"><small>Pacotes reaproveitados</small><strong data-impact-value="7420">7.420</strong><span>Simulado · período selecionado</span></article><article class="stat-card"><small>Resíduos evitados</small><strong data-impact-value="2120" data-unit=" kg">2.120 kg</strong><span>Simulado · metodologia interna</span></article><article class="stat-card"><small>CO₂ evitado</small><strong data-impact-value="5080" data-unit=" kg">5.080 kg</strong><span>Simulado · fator de conversão</span></article><article class="stat-card"><small>Famílias beneficiadas</small><strong data-impact-value="124">124</strong><span>Simulado · cadastros únicos</span></article><article class="stat-card"><small>Instituições apoiadas</small><strong data-impact-value="12">12</strong><span>Simulado · parcerias ativas</span></article><article class="stat-card"><small>Empregos gerados</small><strong data-impact-value="8">8</strong><span>Simulado · diretos e parceiros</span></article></div><div class="dashboard-grid impact-main-grid"><section class="panel"><div class="section-head"><div><h2>Distribuição geográfica</h2><p>Concentração do impacto na Região Metropolitana de Belo Horizonte.</p></div><span class="badge">4 regiões</span></div><div class="impact-map" role="img" aria-label="Mapa demonstrativo da distribuição do impacto"><button class="impact-pin p1 active" data-impact-place="Belo Horizonte · 52%">52%</button><button class="impact-pin p2" data-impact-place="Contagem · 18%">18%</button><button class="impact-pin p3" data-impact-place="Santa Luzia · 12%">12%</button><button class="impact-pin p4" data-impact-place="Ribeirão das Neves · 8%">8%</button><div class="impact-map-label" id="impact-map-label">Belo Horizonte · 52%</div></div><div class="impact-bars"><div><span>Belo Horizonte</span><i style="--value:52%"></i><strong>52%</strong></div><div><span>Contagem</span><i style="--value:18%"></i><strong>18%</strong></div><div><span>Santa Luzia</span><i style="--value:12%"></i><strong>12%</strong></div><div><span>Outras</span><i style="--value:18%"></i><strong>18%</strong></div></div></section><section class="panel"><div class="section-head"><div><h2>Meta anual</h2><p>Progresso demonstrativo para 2026.</p></div><span class="badge">Atualizada diariamente</span></div><div class="impact-goal"><div class="impact-ring"><strong>78%</strong><small>meta 2026</small></div><div><strong>9.750 de 12.500 pacotes</strong><p class="muted">Faltam 2.750 pacotes para a meta anual.</p><div class="notice">Ritmo atual: meta projetada para novembro.</div></div></div><h3>Evolução no período</h3><div class="forecast-chart compact" aria-label="Evolução demonstrativa do impacto"><i style="height:30%"></i><i style="height:38%"></i><i style="height:46%"></i><i style="height:54%"></i><i style="height:63%"></i><i style="height:72%"></i><i style="height:82%"></i><i style="height:92%"></i></div></section></div><section class="panel"><div class="section-head"><div><h2>Instituições e iniciativas apoiadas</h2><p>Parcerias que ampliam o alcance do impacto.</p></div><button class="button secondary" id="impact-export">Exportar relatório</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Instituição</th><th>Região</th><th>Alcance</th><th>Status</th></tr></thead><tbody>${institutions.map(row=>`<tr><td><strong>${row[0]}</strong></td><td>${row[1]}</td><td>${row[2]}</td><td><span class="badge">${row[3]}</span></td></tr>`).join('')}</tbody></table></div></section><div class="dashboard-grid"><section class="panel"><div class="section-head"><div><h2>Emprego e renda</h2><p>Contribuição econômica demonstrativa.</p></div></div><div class="phone-list"><article class="phone-card"><span class="status-icon">8</span><div><strong>Empregos diretos e parceiros</strong><p>Operação, atendimento e logística.</p></div></article><article class="phone-card"><span class="status-icon">28</span><div><strong>Entregadores ativos</strong><p>Renda complementar na rede parceira.</p></div></article><article class="phone-card"><span class="status-icon">R$</span><div><strong>R$ 18.650 de economia gerada</strong><p>Simulado · famílias e comunidade.</p></div></article></div></section><section class="panel"><div class="section-head"><div><h2>Compromissos de transparência</h2><p>Como os números devem ser interpretados.</p></div></div><div class="phone-list"><article class="phone-card"><span class="status-icon">✓</span><div><strong>Natureza identificada</strong><p>Simulado, projetado ou realizado.</p></div></article><article class="phone-card"><span class="status-icon">✓</span><div><strong>Período e atualização</strong><p>Recorte temporal sempre visível.</p></div></article><article class="phone-card"><span class="status-icon">✓</span><div><strong>Fonte e metodologia</strong><p>Rastreabilidade no relatório exportado.</p></div></article></div></section></div></section>`}
