function adminSecurity(){return adminShell(`<div class="dashboard-grid"><section class="panel" id="admin-auth-panel"><span class="eyebrow">Acesso privilegiado</span><h2>Confirme sua identidade</h2><p>Contas administrativas exigem senha e segundo fator.</p><form id="admin-2fa-login"><div class="form-group"><label>E-mail corporativo</label><input class="input" type="email" value="marina@fraldacycle.com.br" required></div><div class="form-group"><label>Senha</label><input class="input" type="password" value="12345678" minlength="8" required></div><small class="field-error" id="admin-auth-error" role="alert"></small><button class="button primary block" type="submit">Continuar com 2FA</button></form></section><aside class="panel"><h2>Proteções do acesso</h2><div class="phone-list"><article class="phone-card"><span class="feedback-icon success">✓</span><div><strong>Autenticação em duas etapas</strong><p>Obrigatória para administradores.</p></div></article><article class="phone-card"><span>⌁</span><div><strong>Sessões monitoradas</strong><p>Dispositivo, horário e localização registrados.</p></div></article><article class="phone-card"><span>♢</span><div><strong>Privilégio mínimo</strong><p>Acesso conforme papel e permissões.</p></div></article></div></aside></div><section class="panel"><div class="section-head"><div><h2>Dispositivos e sessões</h2><p>Controle demonstrativo de acessos privilegiados.</p></div><span class="badge">2FA ativo</span></div>${dataTable([['Chrome · Windows','Belo Horizonte, MG','Agora','Sessão atual'],['Safari · iPhone','Belo Horizonte, MG','Ontem, 18:42','Confiável'],['Firefox · Linux','Contagem, MG','20/07, 09:14','Encerrada']])}</section>`,'security','Segurança e autenticação administrativa')}
function adminRoles(){const permissions=[['users','Usuários e perfis','Criar, editar, suspender e verificar contas'],['ads','Anúncios e catálogo','Moderar anúncios, categorias e produtos'],['operations','Operações','Acompanhar negociações, reservas e entregas'],['finance','Financeiro','Consultar saldos, splits, estornos e conciliação'],['reports','Relatórios','Visualizar, exportar e agendar relatórios'],['settings','Configurações','Alterar regras e parâmetros da plataforma'],['audit','Auditoria','Consultar logs, acessos e evidências']];return adminShell(`<div class="admin-toolbar"><div><span class="eyebrow">Controle de acesso</span><h2>Princípio do menor privilégio</h2><p>Defina somente os acessos necessários para cada função.</p></div><div class="admin-actions"><select class="input" id="rbac-role-select" aria-label="Papel selecionado"><option>Administrador</option><option>Gestor</option><option>Financeiro</option><option>Suporte</option><option>Visualizador</option></select><button class="button secondary" id="rbac-new-role">Novo papel</button></div></div><div class="dashboard-grid"><section class="panel"><div class="section-head"><div><h2>Matriz de permissões</h2><p id="rbac-role-description">Acesso completo com ações críticas protegidas por 2FA.</p></div><span class="badge" id="rbac-user-count">12 usuários</span></div><div class="phone-list" id="rbac-permissions">${permissions.map(([key,title,description])=>`<label class="phone-card"><span class="status-icon">✓</span><div><h3>${title}</h3><p>${description}</p></div><input class="switch" type="checkbox" data-permission="${key}" checked></label>`).join('')}</div><div class="publish-actions action-pair"><button class="button primary" id="rbac-save">Salvar permissões</button><small class="muted" id="rbac-status">Última revisão: hoje, 10:42</small></div></section><aside class="panel"><span class="eyebrow">Proteções aplicadas</span><h2>Governança de acesso</h2><div class="phone-list"><article class="phone-card"><span class="status-icon">✓</span><div><h3>2FA obrigatório</h3><p>Exigido para permissões financeiras, configurações e auditoria.</p></div></article><article class="phone-card"><span class="status-icon">✓</span><div><h3>Revisão trimestral</h3><p>Acessos sem uso e permissões excessivas são sinalizados.</p></div></article><article class="phone-card"><span class="status-icon">✓</span><div><h3>Trilha de auditoria</h3><p>Toda alteração registra responsável, data e permissões modificadas.</p></div></article></div></aside></div><section class="panel"><div class="section-head"><div><h2>Papéis cadastrados</h2><p>Distribuição atual dos acessos administrativos.</p></div><a class="button text" href="#/admin/users">Ver usuários</a></div>${dataTable([['Administrador','Acesso total','12 usuários','2FA obrigatório'],['Gestor','Operação e relatórios','28 usuários','Ativo'],['Financeiro','Financeiro e relatórios','15 usuários','2FA obrigatório'],['Suporte','Usuários e operações','22 usuários','Ativo'],['Visualizador','Somente relatórios','48 usuários','Ativo']])}</section><div id="rbac-role-panel"></div>`,'roles','Papéis e permissões (RBAC)')}
function dataTable(rows){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Nome/ID</th><th>Tipo</th><th>Verificação/Status</th><th>Situação/Valor</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>`<td>${i===2?`<span class="badge ${c.includes('Reservado')?'warn':''}">${c}</span>`:c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function appNotifications(){return appShell(`<div class="phone-content notifications-screen"><div class="screen-title-row"><div><span class="eyebrow">Atualizações</span><h1>Notificações</h1></div><span class="notification-count" id="notification-count" aria-label="4 notificações não lidas">4</span></div><div class="notification-toolbar" aria-label="Filtros de notificações"><div class="notification-filters" role="group" aria-label="Filtrar por assunto"><button class="notification-filter active" type="button" data-notification-filter="all">Todas</button><button class="notification-filter" type="button" data-notification-filter="negotiation">Negociação</button><button class="notification-filter" type="button" data-notification-filter="payment">Pagamentos</button><button class="notification-filter" type="button" data-notification-filter="delivery">Entregas</button><button class="notification-filter" type="button" data-notification-filter="system">Sistema</button></div><label class="notification-unread-toggle"><input id="notification-unread-only" type="checkbox"> Somente não lidas</label></div><div class="feedback-list notification-list" id="notification-list"><article class="feedback-item unread" data-notification-item data-notification-type="payment"><span class="feedback-icon success" aria-hidden="true">✓</span><div class="notification-copy"><div class="notification-meta"><span class="badge success">Pagamento</span><small>Agora</small></div><strong>Pagamento aprovado</strong><p>Seu pagamento de R$ 51,00 está protegido.</p><div class="notification-item-actions"><a href="#/app/payment">Ver pagamento</a><button type="button" data-notification-read>Marcar como lida</button></div></div></article><article class="feedback-item unread" data-notification-item data-notification-type="negotiation"><span class="feedback-icon info" aria-hidden="true">↔</span><div class="notification-copy"><div class="notification-meta"><span class="badge info">Negociação</span><small>Há 3 min</small></div><strong>Nova contraproposta</strong><p>Juliana propôs o valor de R$ 42,00.</p><div class="notification-item-actions"><a href="#/app/proposal-received">Ver proposta</a><button type="button" data-notification-read>Marcar como lida</button></div></div></article><article class="feedback-item unread" data-notification-item data-notification-type="delivery"><span class="feedback-icon warning" aria-hidden="true">⌖</span><div class="notification-copy"><div class="notification-meta"><span class="badge warning">Entrega</span><small>Há 12 min</small></div><strong>Entrega atualizada</strong><p>Seu pedido está a 1,2 km do destino.</p><div class="notification-item-actions"><a href="#/app/delivery">Acompanhar entrega</a><button type="button" data-notification-read>Marcar como lida</button></div></div></article><article class="feedback-item unread" data-notification-item data-notification-type="system"><span class="feedback-icon info" aria-hidden="true">●</span><div class="notification-copy"><div class="notification-meta"><span class="badge info">Sistema</span><small>Há 30 min</small></div><strong>Perfil verificado</strong><p>Seu e-mail e telefone foram validados com sucesso.</p><div class="notification-item-actions"><a href="#/app/profile">Ver perfil</a><button type="button" data-notification-read>Marcar como lida</button></div></div></article><article class="feedback-item" data-notification-item data-notification-type="system"><span class="feedback-icon danger" aria-hidden="true">!</span><div class="notification-copy"><div class="notification-meta"><span class="badge danger">Sistema</span><small>Ontem</small></div><strong>Anúncio indisponível</strong><p>Um item salvo nos favoritos não está mais disponível.</p><div class="notification-item-actions"><a href="#/app/search">Buscar similares</a><span class="notification-read-label">Lida</span></div></div></article></div><div class="notification-empty hidden" id="notification-empty" role="status"><span aria-hidden="true">✓</span><strong>Nenhuma notificação encontrada</strong><p>Altere os filtros ou volte mais tarde.</p></div><button class="button secondary block" id="notification-read-all" type="button">Marcar todas como lidas</button><a class="notification-preferences" href="#/app/notification-settings">Configurar preferências de notificação</a></div>`,'notifications','Notificações e feedback do sistema')}
function appNotificationSettings(){return appShell(`<div class="phone-content notification-settings-screen"><a class="back-link-inline" href="#/app/notifications">← Notificações</a><span class="eyebrow">Preferências</span><h1>Como você quer receber avisos?</h1><p class="muted">Escolha os canais e assuntos. Alertas críticos de segurança permanecem ativos.</p><form id="notification-settings-form"><section class="notification-setting-section"><h2>Canais</h2><article class="phone-card notification-setting-row"><span class="notification-channel-icon">●</span><div><strong>Push no aplicativo</strong><p>Avisos imediatos no celular.</p></div><label class="switch"><input name="channel-push" type="checkbox" checked><span></span></label></article><article class="phone-card notification-setting-row"><span class="notification-channel-icon">✉</span><div><strong>E-mail</strong><p>Resumos e comprovantes importantes.</p></div><label class="switch"><input name="channel-email" type="checkbox" checked><span></span></label></article><article class="phone-card notification-setting-row"><span class="notification-channel-icon">▣</span><div><strong>SMS</strong><p>Códigos e atualizações críticas.</p></div><label class="switch"><input name="channel-sms" type="checkbox"><span></span></label></article></section><section class="notification-setting-section"><h2>Assuntos</h2><label class="notification-topic"><span><strong>Negociações e mensagens</strong><small>Propostas, contrapropostas e chat.</small></span><input name="topic-negotiation" type="checkbox" checked></label><label class="notification-topic"><span><strong>Pagamentos e carteira</strong><small>Aprovações, comprovantes e reembolsos.</small></span><input name="topic-payment" type="checkbox" checked></label><label class="notification-topic"><span><strong>Entregas</strong><small>Coleta, trajeto e confirmação.</small></span><input name="topic-delivery" type="checkbox" checked></label><label class="notification-topic"><span><strong>Favoritos e anúncios</strong><small>Preço, disponibilidade e novos itens.</small></span><input name="topic-marketplace" type="checkbox" checked></label><label class="notification-topic locked"><span><strong>Segurança da conta</strong><small>Login, senha e atividade suspeita.</small></span><input name="topic-security" type="checkbox" checked disabled></label></section><section class="notification-setting-section quiet-hours"><div><h2>Horário silencioso</h2><p>Pause avisos não críticos durante este período.</p></div><label class="switch"><input id="quiet-hours-enabled" name="quiet-enabled" type="checkbox"><span></span></label><div class="quiet-hours-fields" id="quiet-hours-fields" hidden><label>Início<input class="input" name="quiet-start" type="time" value="22:00"></label><label>Fim<input class="input" name="quiet-end" type="time" value="07:00"></label></div></section><div class="notice info">Alertas de segurança, pagamento e entrega em andamento podem ser enviados mesmo no horário silencioso.</div><p class="settings-save-status" id="notification-settings-status" role="status" aria-live="polite"></p><button class="button primary block" type="submit">Salvar preferências</button><button class="button ghost block" id="notification-settings-reset" type="button">Restaurar padrão</button></form></div>`,'profile','Preferências de notificações')}
