  const rolePermissions={Administrador:['users','ads','operations','finance','reports','settings','audit'],Gestor:['users','ads','operations','reports'],Financeiro:['finance','reports','audit'],Suporte:['users','ads','operations'],Visualizador:['reports']};const roleMeta={Administrador:['12 usuários','Acesso completo com ações críticas protegidas por 2FA.'],Gestor:['28 usuários','Gestão operacional, anúncios e relatórios.'],Financeiro:['15 usuários','Conciliação, estornos, splits e relatórios financeiros.'],Suporte:['22 usuários','Atendimento, usuários, anúncios e operações.'],Visualizador:['48 usuários','Consulta de relatórios sem permissão de alteração.']};const roleSelect=document.getElementById('rbac-role-select');const applyRole=()=>{if(!roleSelect)return;const allowed=rolePermissions[roleSelect.value]||[];document.querySelectorAll('[data-permission]').forEach(input=>input.checked=allowed.includes(input.dataset.permission));const meta=roleMeta[roleSelect.value]||['0 usuários','Papel personalizado.'];document.getElementById('rbac-user-count').textContent=meta[0];document.getElementById('rbac-role-description').textContent=meta[1]};roleSelect?.addEventListener('change',applyRole);document.getElementById('rbac-save')?.addEventListener('click',()=>{document.getElementById('rbac-status').textContent=`Alteração registrada por Marina Lima · ${new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}`;notify(`Permissões do papel ${roleSelect.value} atualizadas`)});document.getElementById('rbac-new-role')?.addEventListener('click',()=>{document.getElementById('rbac-role-panel').innerHTML='<section class="panel"><div class="section-head"><div><span class="eyebrow">Novo papel</span><h2>Criar conjunto de acessos</h2></div></div><form id="rbac-new-role-form" class="admin-filters"><input class="input" name="role" required placeholder="Nome do papel"><input class="input" name="description" required placeholder="Descrição e responsabilidade"><button class="button primary" type="submit">Criar papel</button></form></section>';document.getElementById('rbac-new-role-form').addEventListener('submit',event=>{event.preventDefault();const name=new FormData(event.currentTarget).get('role').trim();if(!name)return;rolePermissions[name]=[];roleMeta[name]=['0 usuários','Papel personalizado sem permissões iniciais.'];roleSelect.insertAdjacentHTML('beforeend',`<option>${name}</option>`);roleSelect.value=name;applyRole();event.currentTarget.closest('.panel').remove();notify(`Papel ${name} criado com sucesso`)})});applyRole();
