function normalizeText(value){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function blockedChatContent(value){const normalized=normalizeText(value);const digits=value.replace(/\D/g,'');const phonePattern=/(?:\+?55[\s.-]*)?(?:\(?\d{2}\)?[\s.-]*)?(?:9?[\s.-]*\d{4})[\s.-]*\d{4}/;const linkPattern=/(?:https?:\/\/|www\.|\b[a-z0-9-]+\.(?:com|com\.br|net|org|io|app|me|link)\b|bit\.ly|linktr\.ee)/i;const emailPattern=/\b[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}\b/i;const writtenEmail=/(?:arroba|at)\s*(?:gmail|hotmail|outlook|yahoo)|(?:gmail|hotmail|outlook|yahoo)\s*(?:ponto|dot)/;const socialPattern=/\b(?:instagram|insta|facebook|face\s*book|fb|perfil\s+social)\b|@[a-z0-9._]{3,}/i;const qrPattern=/\b(?:qr\s*code|qrcode|codigo\s*qr)\b/i;const numberWords=['zero','um','uma','dois','duas','tres','quatro','cinco','seis','sete','oito','nove'];const writtenDigits=normalized.split(/[^a-z]+/).filter(word=>numberWords.includes(word)).length;if(phonePattern.test(value)||digits.length>=8||writtenDigits>=7)return'Telefones não podem ser compartilhados no chat.';if(emailPattern.test(value)||writtenEmail.test(normalized))return'E-mails não podem ser compartilhados no chat.';if(linkPattern.test(value))return'Links externos não podem ser compartilhados no chat.';if(qrPattern.test(normalized))return'QR Codes não podem ser compartilhados no chat.';if(socialPattern.test(normalized))return'Perfis do Instagram, Facebook ou outras redes não podem ser compartilhados no chat.';return''}
function setupProtectedChat(){const form=document.getElementById('chat-form');if(!form)return;const input=document.getElementById('msg');const error=document.getElementById('chat-error');form.addEventListener('submit',event=>{event.preventDefault();const message=input.value.trim();if(!message){error.textContent='Digite uma mensagem para enviar.';input.classList.add('invalid');return}const blocked=blockedChatContent(message);if(blocked){error.textContent=blocked+' Mantenha toda a negociação dentro da FraldaCycle.';input.classList.add('invalid');notify('Mensagem bloqueada por segurança');return}error.textContent='';input.classList.remove('invalid');document.getElementById('message-list').insertAdjacentHTML('beforeend',`<div class="message me">${escapeHtml(message)}</div>`);input.value='';notify('Mensagem enviada com segurança')});input.addEventListener('input',()=>{error.textContent='';input.classList.remove('invalid')})}
function setupSafetyActions(){const content=document.getElementById('safety-content');if(!content)return;const form=document.getElementById('safety-form');const reason=document.getElementById('safety-reason');const details=document.getElementById('safety-details');const error=document.getElementById('safety-error');form?.addEventListener('submit',event=>{event.preventDefault();if(!reason.value){error.textContent='Selecione o motivo da denúncia.';reason.classList.add('invalid');reason.focus();return}if(details.value.trim().length<10){error.textContent='Descreva o ocorrido com pelo menos 10 caracteres.';details.classList.add('invalid');details.focus();return}const button=form.querySelector('[type="submit"]');button.disabled=true;button.innerHTML='<span class="inline-spinner"></span> Enviando para análise...';setTimeout(()=>{content.innerHTML='<a class="back-link-inline" href="#/app/chat">← Conversa</a><div class="ui-state success-state"><div class="state-icon success">✓</div><span class="eyebrow">Registro protegido</span><h1>Denúncia enviada</h1><p>A equipe de segurança analisará a conversa e as evidências preservadas.</p><div class="notice">Protocolo #SEG-2841 · Você receberá uma atualização nas notificações.</div><a class="button primary block" href="#/app/home">Voltar ao início</a></div>';notify('Denúncia enviada para análise')},600)});document.getElementById('block-user')?.addEventListener('click',event=>{const button=event.currentTarget;button.disabled=true;button.innerHTML='<span class="inline-spinner"></span> Bloqueando...';setTimeout(()=>{content.innerHTML='<a class="back-link-inline" href="#/app/home">← Início</a><div class="ui-state error-state"><div class="state-icon danger">×</div><span class="eyebrow">Usuário bloqueado</span><h1>Conversa indisponível</h1><p>Juliana não poderá enviar novas mensagens ou propostas para você.</p><div class="notice">O conteúdo anterior foi preservado para segurança. Você pode revisar o bloqueio em Configurações e privacidade.</div><a class="button primary block" href="#/app/home">Voltar ao início</a></div>';notify('Usuário bloqueado com sucesso')},500)})}
function setupWalletLogisticsExtras(){document.getElementById('wallet-card-add')?.addEventListener('click',()=>{const panel=document.getElementById('wallet-card-panel');panel.innerHTML='<div class="panel"><div class="form-group"><label>Número do cartão</label><input class="input" inputmode="numeric" placeholder="0000 0000 0000 0000"></div><div class="form-row"><div class="form-group"><label>Validade</label><input class="input" placeholder="MM/AA"></div><div class="form-group"><label>CVV</label><input class="input" inputmode="numeric" placeholder="000"></div></div><button class="button primary block" id="wallet-card-save">Salvar cartão</button></div>';document.getElementById('wallet-card-save')?.addEventListener('click',event=>{event.currentTarget.disabled=true;event.currentTarget.textContent='Cartão tokenizado com segurança';notify('Cartão adicionado com segurança')})});document.querySelectorAll('[data-action="remove-card"]').forEach(button=>button.addEventListener('click',()=>{button.closest('.phone-card')?.remove();notify('Cartão removido')}));document.getElementById('dispute-submit')?.addEventListener('click',event=>{const reason=document.getElementById('dispute-reason');const details=document.getElementById('dispute-details');const error=document.getElementById('dispute-error');if(!reason.value||details.value.trim().length<10){error.textContent='Selecione o motivo e descreva o ocorrido com pelo menos 10 caracteres.';return}const content=document.getElementById('dispute-content');event.currentTarget.disabled=true;event.currentTarget.innerHTML='<span class="inline-spinner"></span> Registrando...';setTimeout(()=>{content.innerHTML='<a class="back-link-inline" href="#/app/wallet">← Carteira</a><div class="ui-state success-state"><div class="state-icon success">✓</div><span class="eyebrow">Mediação iniciada</span><h1>Disputa registrada</h1><p>O valor permanece protegido enquanto a equipe analisa as evidências.</p><div class="notice">Protocolo #MED-4827 · Retorno estimado em até 2 dias úteis.</div><a class="button primary block" href="#/app/wallet">Voltar à carteira</a></div>';notify('Disputa enviada para mediação')},500)});document.getElementById('reschedule-submit')?.addEventListener('click',event=>{event.currentTarget.disabled=true;event.currentTarget.textContent='Entrega reagendada';document.getElementById('reschedule-content')?.insertAdjacentHTML('beforeend','<div class="notice success-notice">Nova janela confirmada. Entregador e vendedor foram notificados.</div>');notify('Entrega reagendada com sucesso')})}
function courierHome(){return appShell(`<div class="phone-content"><div class="screen-title-row"><div><span class="eyebrow">Olá, Carlos</span><h1>Minhas entregas</h1></div><span class="badge">Online</span></div><div class="stat-grid"><article class="stat-card"><small>Hoje</small><strong>5</strong><span>entregas</span></article><article class="stat-card"><small>Ganhos</small><strong>R$ 86,50</strong><span>estimados</span></article></div><div class="notice">Você está disponível para novas rotas em Belo Horizonte.</div><div class="section-head compact"><h2>Próxima coleta</h2><span class="badge warn">15:30</span></div><div class="phone-list"><a class="phone-card" href="#/courier/job"><span class="status-icon">1</span><div><h3>Pedido #FC-8F3A2B</h3><p>Coleta no Bairro Castelo · entrega em Contagem</p><strong>Repasse: R$ 19,00</strong></div><span>›</span></a><article class="phone-card"><span class="status-icon">2</span><div><h3>Pedido #FC-7D1E9C</h3><p>Agendada · 16:00–16:30</p></div><span>›</span></article></div><a class="button secondary block" href="#/courier/history">Histórico e repasses</a></div>`,'courier','Área do entregador')}
function courierJob(){return appShell(`<div class="phone-content"><a class="back-link-inline" href="#/courier/home">← Entregas</a><span class="eyebrow">Nova rota disponível</span><h1>Detalhes da coleta</h1><div class="delivery-map tracking-map" aria-label="Mapa da rota"><div class="delivery-route">⌖</div><span class="tracking-origin">Coleta</span><span class="tracking-destination">Destino</span></div><div class="phone-list"><article class="phone-card"><span>▣</span><div><strong>Coleta</strong><p>Bairro Castelo, Belo Horizonte · 15:30</p></div></article><article class="phone-card"><span>⌖</span><div><strong>Entrega</strong><p>Centro, Contagem · até 16:00</p></div></article><article class="phone-card"><span>◇</span><div><strong>Pacote e proteção</strong><p>Fraldas fechadas · seguro ativo</p></div></article><article class="phone-card"><span>R$</span><div><strong>Repasse</strong><p>R$ 19,00 · liberado após comprovação</p></div></article></div><div class="publish-actions action-pair"><a class="button secondary" href="#/courier/home">Recusar</a><a class="button primary" href="#/courier/route">Aceitar rota</a></div></div>`,'courier','Aceite seguro da rota')}
function courierRoute(){return appShell(`<div class="phone-content"><div class="screen-title-row"><div><span class="eyebrow">Pedido #FC-8F3A2B</span><h1>Rota em andamento</h1></div><span class="badge">Em trânsito</span></div><div class="delivery-map tracking-map" aria-label="Navegação da entrega"><div class="delivery-route">⌖</div><span class="tracking-origin">Coleta</span><span class="tracking-driver">●</span><span class="tracking-destination">Destino</span></div><div class="notice">Próximo destino a 1,2 km · chegada estimada 15:52</div><div class="steps"><div class="step active"><div class="step-num">✓</div><div><strong>Coleta confirmada</strong><p class="muted">Foto do pacote registrada · 15:34</p></div></div><div class="step active"><div class="step-num">●</div><div><strong>Em trânsito</strong><p class="muted">Rota monitorada em tempo real</p></div></div><div class="step"><div class="step-num">3</div><div><strong>Comprovar entrega</strong><p class="muted">Foto, localização e recebedor</p></div></div></div><a class="button secondary block" href="#/app/chat">Chat protegido com o usuário</a><a class="button primary block" href="#/courier/proof">Cheguei ao destino</a></div>`,'courier','Rastreamento do entregador')}
function courierProof(){return appShell(`<div class="phone-content"><a class="back-link-inline" href="#/courier/route">← Rota</a><span class="eyebrow">Comprovação protegida</span><h1>Finalizar entrega</h1><div class="panel" style="min-height:170px;display:grid;place-items:center;background:var(--green-50)"><div style="text-align:center"><span class="state-icon">▣</span><h3>Foto do pacote</h3><p class="muted">Localização e horário serão registrados.</p><button class="button secondary">Adicionar foto</button></div></div><div class="form-group"><label>Nome de quem recebeu</label><input class="input" value="Ana Souza"></div><label class="terms"><input type="checkbox" checked> Confirmo que o pacote foi entregue sem avarias.</label><a class="button primary block" href="#/courier/history" data-action="delivery">Registrar prova e concluir</a><div class="notice">O repasse será liberado em até 24 horas após a confirmação.</div></div>`,'courier','Prova de entrega')}
function courierHistory(){return appShell(`<div class="phone-content"><a class="back-link-inline" href="#/courier/home">← Painel</a><span class="eyebrow">Transparência financeira</span><h1>Histórico e repasses</h1><div class="stat-grid"><article class="stat-card"><small>Entregas no mês</small><strong>48</strong><span>97,2% no prazo</span></article><article class="stat-card"><small>Saldo a receber</small><strong>R$ 86,50</strong><span>4 entregas</span></article></div><div class="phone-list"><article class="phone-card"><span class="status-icon">✓</span><div><h3>#FC-8F3A2B</h3><p>Concluída hoje · comprovante validado</p><strong>R$ 19,00 · processamento</strong></div></article><article class="phone-card"><span class="status-icon">✓</span><div><h3>#FC-7A18D4</h3><p>Concluída ontem · repasse realizado</p><strong>R$ 22,50</strong></div></article><article class="phone-card"><span class="status-icon">✓</span><div><h3>#FC-62E91A</h3><p>Concluída em 22/07 · repasse realizado</p><strong>R$ 18,00</strong></div></article></div><div class="notice">Avaliação média 4,9 ★ · cobertura de seguro ativa em todas as entregas.</div></div>`,'courier','Histórico do entregador')}
function escapeHtml(value){return value.replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function actionMessage(action){return {favorite:'Adicionado aos favoritos',search:'128 resultados encontrados',send:'Mensagem enviada',pay:'Pagamento aprovado e protegido',receipt:'Comprovante preparado para visualização',delivery:'Recebimento confirmado',publish:'Opção selecionada. Avançando para a próxima etapa',invite:'Convite enviado',export:'Relatório preparado para exportação','read-all':'Todas as notificações foram marcadas como lidas','add-balance':'Opções para adicionar saldo abertas',refund:'Solicitação de reembolso enviada','delivery-problem':'Atendimento de entrega iniciado',rating:'Avaliação enviada com sucesso','publish-complete':'Anúncio publicado com sucesso'}[action]||'Ação concluída'}
document.getElementById('theme-toggle').addEventListener('click',()=>{const html=document.documentElement;const next=html.dataset.theme==='dark'?'light':'dark';html.dataset.theme=next;localStorage.setItem('fc-theme',next);notify(`Tema ${next==='dark'?'escuro':'claro'} ativado`)})
document.documentElement.dataset.theme=localStorage.getItem('fc-theme')||'light';window.addEventListener('hashchange',render);render();
function appStateOffline(){return appShell(`<div class="phone-content"><div class="ui-state error-state"><div class="state-icon danger">!</div><span class="eyebrow">Sem conexão</span><h1>Você está offline</h1><p>Não conseguimos atualizar anúncios, mensagens e entregas agora.</p><div class="notice">As informações já carregadas continuam disponíveis. Nenhuma ação será perdida.</div><a class="button primary block" href="#/app/home">Tentar novamente</a><a class="button secondary block" href="#/app/help">Abrir ajuda offline</a></div></div>`,'home','Estado offline')}
function appStatePermission(){return appShell(`<div class="phone-content"><div class="ui-state error-state"><div class="state-icon danger">⌖</div><span class="eyebrow">Permissão necessária</span><h1>Localização desativada</h1><p>Permita o acesso à localização para ver anúncios próximos e acompanhar entregas no mapa.</p><div class="notice">Você mantém o controle: a localização é usada somente durante recursos que dependem dela.</div><button class="button primary block" data-action="permission">Abrir configurações</button><a class="button secondary block" href="#/app/search">Continuar sem localização</a></div></div>`,'search','Permissão negada')}
function appStateRemoved(){return appShell(`<div class="phone-content"><a class="back-link-inline" href="#/app/search">← Resultados</a><div class="ui-state empty-state"><div class="state-icon">×</div><span class="eyebrow">Conteúdo indisponível</span><h1>Este anúncio foi removido</h1><p>O item pode ter sido negociado, excluído pelo anunciante ou retirado após uma análise de segurança.</p><div class="notice">Se havia uma negociação ativa, o histórico e as evidências permanecem protegidos.</div><a class="button primary block" href="#/app/search">Ver anúncios semelhantes</a><a class="button secondary block" href="#/app/help">Preciso de ajuda</a></div></div>`,'search','Conteúdo removido')}
function adminAds(){const rows=[['#AN-2841','Pampers Confort M · 50 un.','Juliana Silva','Publicado','R$ 45,00'],['#AN-2840','Huggies Supreme G · 40 un.','Ana Souza','Em revisão','R$ 40,00'],['#AN-2839','Babysec Premium P · 60 un.','Mariana Costa','Pausado','Doação'],['#AN-2838','MamyPoko Fralda-Calça XG','Carla Mendes','Sinalizado','R$ 38,00']];return adminShell(`<div class="admin-toolbar"><div><span class="eyebrow">Catálogo e moderação</span><h2>Anúncios e produtos</h2><p>Revise qualidade, segurança, disponibilidade e categorização dos anúncios.</p></div><button class="button primary" id="admin-ad-new">Adicionar produto</button></div><div class="stat-grid"><article class="stat-card"><small>Anúncios ativos</small><strong>6.421</strong><span>+10% no mês</span></article><article class="stat-card"><small>Em revisão</small><strong>18</strong><span>prazo médio 24 min</span></article><article class="stat-card"><small>Sinalizados</small><strong>4</strong><span>prioridade alta</span></article><article class="stat-card"><small>Estoque publicado</small><strong>12.580</strong><span>pacotes fechados</span></article></div><section class="panel"><div class="admin-filters"><input class="input" id="admin-ad-search" placeholder="Buscar anúncio, produto ou anunciante"><select class="input" id="admin-ad-status"><option value="">Todos os status</option><option>Publicado</option><option>Em revisão</option><option>Pausado</option><option>Sinalizado</option></select><select class="input" id="admin-ad-category"><option value="">Todas as categorias</option><option>Fraldas</option><option>Higiene</option><option>Roupas</option></select></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>ID</th><th>Produto</th><th>Anunciante</th><th>Status</th><th>Valor</th><th>Ações</th></tr></thead><tbody id="admin-ad-rows">${rows.map(row=>`<tr data-admin-ad data-search="${row.join(' ').toLowerCase()}"><td>${row[0]}</td><td>${row[1]}</td><td>${row[2]}</td><td><span class="badge">${row[3]}</span></td><td>${row[4]}</td><td><div class="admin-actions"><button class="button text" data-ad-action="review">Revisar</button><button class="button text" data-ad-action="pause">Pausar</button><button class="button text danger-text" data-ad-action="remove">Remover</button></div></td></tr>`).join('')}</tbody></table></div><p class="empty-message" id="admin-ad-empty" hidden>Nenhum anúncio corresponde aos filtros.</p></section><div id="admin-ad-review"></div>`,'ads','Anúncios e produtos')}
function setupAdminAds(){const search=document.getElementById('admin-ad-search');const status=document.getElementById('admin-ad-status');if(!search||!status)return;const filter=()=>{let visible=0;document.querySelectorAll('[data-admin-ad]').forEach(row=>{const matchText=row.dataset.search.includes(search.value.trim().toLowerCase());const matchStatus=!status.value||row.dataset.search.includes(status.value.toLowerCase());row.hidden=!(matchText&&matchStatus);if(!row.hidden)visible++});document.getElementById('admin-ad-empty').hidden=visible>0};search.addEventListener('input',filter);status.addEventListener('change',filter);document.querySelectorAll('[data-ad-action]').forEach(button=>button.addEventListener('click',()=>{const row=button.closest('[data-admin-ad]');const id=row.cells[0].textContent;const product=row.cells[1].textContent;if(button.dataset.adAction==='remove'){row.remove();notify(`${id} removido do catálogo`);filter();return}if(button.dataset.adAction==='pause'){row.cells[3].innerHTML='<span class="badge warn">Pausado</span>';notify(`${id} pausado`);return}document.getElementById('admin-ad-review').innerHTML=`<section class="panel"><div class="section-head"><div><span class="eyebrow">Revisão de anúncio</span><h2>${product}</h2><p>${id} · verificação de conteúdo, imagens e regras comerciais.</p></div><span class="badge">Em análise</span></div><div class="dashboard-grid"><div class="phone-list"><article class="phone-card"><span class="status-icon">✓</span><div><h3>Produto fechado</h3><p>Lacre e validade identificados nas imagens.</p></div></article><article class="phone-card"><span class="status-icon">✓</span><div><h3>Categoria e tamanho</h3><p>Marca, tamanho e quantidade coerentes.</p></div></article><article class="phone-card"><span class="status-icon">!</span><div><h3>Preço e descrição</h3><p>Requer confirmação manual antes da publicação.</p></div></article></div><div><label class="form-group">Observação ao anunciante<textarea class="input" rows="4" placeholder="Explique ajustes necessários"></textarea></label><div class="publish-actions action-pair"><button class="button secondary" id="admin-ad-request">Solicitar ajuste</button><button class="button primary" id="admin-ad-approve">Aprovar anúncio</button></div></div></div></section>`;document.getElementById('admin-ad-approve').addEventListener('click',()=>{row.cells[3].innerHTML='<span class="badge">Publicado</span>';document.getElementById('admin-ad-review').innerHTML='';notify(`${id} aprovado e publicado`)});document.getElementById('admin-ad-request').addEventListener('click',()=>notify(`Ajustes solicitados para ${id}`))}));document.getElementById('admin-ad-new')?.addEventListener('click',()=>notify('Cadastro administrativo de produto iniciado'))}
function adminModeration(){const cases=[['#SEG-2841','Compartilhamento de contato','Chat · Juliana S. e Ana S.','Alta','Novo'],['#SEG-2838','Comportamento suspeito','Conta · Usuário #1842','Crítica','Em análise'],['#SEG-2831','Produto divergente','Anúncio #AN-2810','Média','Novo'],['#SEG-2826','Tentativas de fraude','Pagamento #PG-9912','Crítica','Escalado']];return adminShell(`<div class="admin-toolbar"><div><span class="eyebrow">Confiança e proteção</span><h2>Fila de moderação e antifraude</h2><p>Analise denúncias, sinais automáticos e evidências preservadas antes de decidir.</p></div><button class="button secondary" id="moderation-refresh">Atualizar fila</button></div><div class="stat-grid"><article class="stat-card"><small>Casos abertos</small><strong>24</strong><span>4 críticos</span></article><article class="stat-card"><small>Tempo médio</small><strong>18 min</strong><span>-12% no mês</span></article><article class="stat-card"><small>Bloqueios preventivos</small><strong>7</strong><span>últimas 24h</span></article><article class="stat-card"><small>Precisão antifraude</small><strong>96,8%</strong><span>modelo demonstrativo</span></article></div><section class="panel"><div class="admin-filters"><input class="input" id="moderation-search" placeholder="Buscar caso, pessoa ou referência"><select class="input" id="moderation-priority"><option value="">Todas as prioridades</option><option>Crítica</option><option>Alta</option><option>Média</option></select><select class="input" id="moderation-status"><option value="">Todos os status</option><option>Novo</option><option>Em análise</option><option>Escalado</option></select></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Caso</th><th>Motivo</th><th>Origem</th><th>Prioridade</th><th>Status</th><th>Ação</th></tr></thead><tbody>${cases.map(row=>`<tr data-moderation-case data-search="${row.join(' ').toLowerCase()}"><td>${row[0]}</td><td>${row[1]}</td><td>${row[2]}</td><td><span class="badge ${row[3]==='Crítica'?'danger-badge':row[3]==='Alta'?'warn':''}">${row[3]}</span></td><td>${row[4]}</td><td><button class="button text" data-case-review>Analisar</button></td></tr>`).join('')}</tbody></table></div><p class="empty-message" id="moderation-empty" hidden>Nenhum caso corresponde aos filtros.</p></section><div id="moderation-case-panel"></div><section class="panel"><div class="section-head"><div><h2>Histórico de decisões</h2><p>Registro imutável das ações de moderação.</p></div><span class="badge">Auditoria ativa</span></div>${dataTable([['#SEG-2818','Anúncio removido','Marina Lima','Hoje, 10:42'],['#SEG-2814','Usuário advertido','João Martins','Hoje, 09:55'],['#SEG-2809','Conta bloqueada','Marina Lima','Ontem, 18:20'],['#SEG-2801','Caso encerrado sem infração','Ana Pereira','Ontem, 16:04']])}</section>`,'moderation','Moderação, segurança e antifraude')}
function setupAdminModeration(){const search=document.getElementById('moderation-search');if(!search)return;const priority=document.getElementById('moderation-priority');const status=document.getElementById('moderation-status');const filter=()=>{let visible=0;document.querySelectorAll('[data-moderation-case]').forEach(row=>{const text=row.dataset.search;const match=text.includes(search.value.trim().toLowerCase())&&(!priority.value||text.includes(priority.value.toLowerCase()))&&(!status.value||text.includes(status.value.toLowerCase()));row.hidden=!match;if(match)visible++});document.getElementById('moderation-empty').hidden=visible>0};search.addEventListener('input',filter);priority.addEventListener('change',filter);status.addEventListener('change',filter);document.getElementById('moderation-refresh')?.addEventListener('click',()=>notify('Fila de moderação atualizada'));document.querySelectorAll('[data-case-review]').forEach(button=>button.addEventListener('click',()=>{const row=button.closest('[data-moderation-case]');const id=row.cells[0].textContent;document.getElementById('moderation-case-panel').innerHTML=`<section class="panel"><div class="section-head"><div><span class="eyebrow">Análise do caso ${id}</span><h2>${row.cells[1].textContent}</h2><p>${row.cells[2].textContent} · evidências preservadas.</p></div><span class="badge warn">Decisão pendente</span></div><div class="dashboard-grid"><div class="phone-list"><article class="phone-card"><span class="status-icon">!</span><div><h3>Regra acionada</h3><p>Conteúdo bloqueado automaticamente pela política de segurança.</p></div></article><article class="phone-card"><span class="status-icon">✓</span><div><h3>Evidência íntegra</h3><p>Mensagem, horário, participantes e contexto foram preservados.</p></div></article><article class="phone-card"><span class="status-icon">✓</span><div><h3>Histórico verificado</h3><p>Nenhuma punição anterior nos últimos 90 dias.</p></div></article></div><div><div class="form-group"><label>Fundamentação da decisão</label><textarea class="input" id="moderation-note" rows="4" placeholder="Registre os critérios utilizados"></textarea><small class="field-error" id="moderation-error"></small></div><div class="publish-actions"><button class="button secondary" data-moderation-decision="dismiss">Sem infração</button><button class="button secondary" data-moderation-decision="warn">Advertir</button><button class="button primary" data-moderation-decision="block">Bloquear conta</button></div></div></div></section>`;document.querySelectorAll('[data-moderation-decision]').forEach(decision=>decision.addEventListener('click',()=>{const note=document.getElementById('moderation-note');if(note.value.trim().length<10){document.getElementById('moderation-error').textContent='Registre uma justificativa com pelo menos 10 caracteres.';return}const labels={dismiss:'Encerrado sem infração',warn:'Usuário advertido',block:'Conta bloqueada'};row.cells[4].innerHTML=`<span class="badge">${labels[decision.dataset.moderationDecision]}</span>`;document.getElementById('moderation-case-panel').innerHTML='';notify(`${id}: ${labels[decision.dataset.moderationDecision]}`)}))}))}
function adminAudit(){const auditRows=[['24/07 11:42:18','Marina Lima','Anúncio #AN-2810 removido','Moderação','200.184.17.8'],['24/07 11:35:04','Carlos Silva','Permissão financeira alterada','Acessos','200.184.17.21'],['24/07 11:28:51','Sistema','Pagamento #PG-9912 conciliado','Financeiro','worker-pay-03'],['24/07 11:20:17','Ana Pereira','Relatório operacional exportado','Relatórios','200.184.19.4']];const webhookRows=[['payment.approved','#WH-84721','Pagamento','Entregue','218 ms'],['delivery.updated','#WH-84718','Logística','Entregue','184 ms'],['ad.moderated','#WH-84716','Moderação','Falhou','3 tentativas'],['refund.requested','#WH-84712','Financeiro','Pendente','Aguardando']];return adminShell(`<div class="admin-toolbar"><div><span class="eyebrow">Observabilidade e conformidade</span><h2>Logs, auditoria e webhooks</h2><p>Rastreabilidade de ações administrativas, eventos técnicos e integrações externas.</p></div><button class="button secondary" id="audit-refresh">Atualizar eventos</button></div><div class="stat-grid"><article class="stat-card"><small>Eventos nas últimas 24h</small><strong>12.842</strong><span>retenção: 180 dias</span></article><article class="stat-card"><small>Webhooks entregues</small><strong>99,94%</strong><span>últimas 24h</span></article><article class="stat-card"><small>Falhas abertas</small><strong>2</strong><span>uma requer atenção</span></article><article class="stat-card"><small>Integridade da trilha</small><strong>100%</strong><span>assinatura verificada</span></article></div><section class="panel"><div class="section-head"><div><h2>Trilha de auditoria</h2><p>Registro imutável de quem fez o quê, quando e de onde.</p></div><button class="button text" id="audit-export">Exportar CSV</button></div><div class="admin-filters"><input class="input" id="audit-search" placeholder="Buscar pessoa, ação, módulo ou IP"><select class="input" id="audit-module"><option value="">Todos os módulos</option><option>Moderação</option><option>Acessos</option><option>Financeiro</option><option>Relatórios</option></select><select class="input" id="audit-period"><option>Últimas 24 horas</option><option>Últimos 7 dias</option><option>Últimos 30 dias</option></select></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Data e hora</th><th>Responsável</th><th>Ação</th><th>Módulo</th><th>Origem</th></tr></thead><tbody>${auditRows.map(row=>`<tr data-audit-row data-search="${row.join(' ').toLowerCase()}">${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="empty-message" id="audit-empty" hidden>Nenhum evento corresponde aos filtros.</p></section><div class="dashboard-grid"><section class="panel"><div class="section-head"><div><h2>Monitor de webhooks</h2><p>Entregas, tentativas e latência das integrações.</p></div><span class="badge">Assinatura HMAC ativa</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Evento</th><th>ID</th><th>Domínio</th><th>Status</th><th>Resposta</th><th>Ação</th></tr></thead><tbody>${webhookRows.map((row,index)=>`<tr><td>${row[0]}</td><td>${row[1]}</td><td>${row[2]}</td><td><span class="badge ${row[3]==='Falhou'?'danger-badge':row[3]==='Pendente'?'warn':''}">${row[3]}</span></td><td>${row[4]}</td><td>${row[3]==='Falhou'?`<button class="button text" data-webhook-retry="${index}">Reprocessar</button>`:'—'}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="section-head"><div><h2>Logs técnicos</h2><p>Saúde dos serviços em tempo real.</p></div><span class="badge">Streaming ativo</span></div><div class="phone-list"><article class="phone-card"><span class="status-dot online"></span><div><strong>API Gateway</strong><p>200 · GET /api/health · 42 ms</p></div><small>agora</small></article><article class="phone-card"><span class="status-dot online"></span><div><strong>Pagamentos</strong><p>INFO · conciliação concluída</p></div><small>12 s</small></article><article class="phone-card"><span class="status-dot warning"></span><div><strong>Webhook worker</strong><p>WARN · resposta 503 do destino</p></div><small>31 s</small></article><article class="phone-card"><span class="status-dot online"></span><div><strong>Logística</strong><p>INFO · localização atualizada</p></div><small>48 s</small></article></div><div class="notice">Dados sensíveis são mascarados. Acesso e exportação também ficam registrados na auditoria.</div></section></div>`,'audit','Logs, auditoria e webhooks')}
function setupAdminAudit(){const search=document.getElementById('audit-search');if(!search)return;const module=document.getElementById('audit-module');const filter=()=>{let visible=0;document.querySelectorAll('[data-audit-row]').forEach(row=>{const text=row.dataset.search;const match=text.includes(search.value.trim().toLowerCase())&&(!module.value||text.includes(module.value.toLowerCase()));row.hidden=!match;if(match)visible++});document.getElementById('audit-empty').hidden=visible>0};search.addEventListener('input',filter);module.addEventListener('change',filter);document.getElementById('audit-refresh')?.addEventListener('click',()=>notify('Eventos e logs atualizados'));document.getElementById('audit-export')?.addEventListener('click',()=>notify('Exportação da auditoria preparada com mascaramento de dados'));document.querySelectorAll('[data-webhook-retry]').forEach(button=>button.addEventListener('click',()=>{const row=button.closest('tr');button.disabled=true;button.textContent='Reprocessando…';window.setTimeout(()=>{row.cells[3].innerHTML='<span class="badge">Entregue</span>';row.cells[4].textContent='226 ms';row.cells[5].textContent='—';notify('Webhook reprocessado e entregue com sucesso')},700)}))}
