function setupAdminData(){const run=document.getElementById('data-run-pipeline');if(!run)return;run.addEventListener('click',()=>{run.disabled=true;run.textContent='Executando…';window.setTimeout(()=>{run.disabled=false;run.textContent='Executar pipeline';notify('Pipeline executado; qualidade e linhagem validadas')},800)});document.querySelectorAll('[data-job-run]').forEach(button=>button.addEventListener('click',()=>{const row=button.closest('tr');button.disabled=true;button.textContent='Executando…';row.cells[1].innerHTML='<span class="badge">Executando</span>';window.setTimeout(()=>{row.cells[1].innerHTML='<span class="badge">Concluído</span>';row.cells[2].textContent='Agora';button.disabled=false;button.textContent='Executar';notify(`${row.cells[0].textContent}: carga concluída`)},650)}));const search=document.getElementById('data-search');search.addEventListener('input',()=>{let visible=0;document.querySelectorAll('[data-data-table]').forEach(row=>{const match=row.dataset.search.includes(search.value.trim().toLowerCase());row.hidden=!match;if(match)visible++});document.getElementById('data-empty').hidden=visible>0});document.getElementById('data-domain')?.addEventListener('change',event=>{const term=event.target.value.toLowerCase();document.querySelectorAll('[data-data-job]').forEach(row=>row.hidden=Boolean(term)&&!row.dataset.domain.includes(term))});document.getElementById('data-quality-report')?.addEventListener('click',()=>notify('Relatório de qualidade atualizado'));document.getElementById('data-incident')?.addEventListener('click',()=>notify('Formulário de incidente de dados aberto'))}
