function setupAdminPartnerships(){const search=document.getElementById('partner-search');if(!search)return;const status=document.getElementById('partner-status');const filter=()=>{let visible=0;document.querySelectorAll('[data-partner-row]').forEach(row=>{const text=row.dataset.search;const match=text.includes(search.value.trim().toLowerCase())&&(!status.value||text.includes(status.value.toLowerCase()));row.hidden=!match;if(match)visible++});document.getElementById('partner-empty').hidden=visible>0};search.addEventListener('input',filter);status.addEventListener('change',filter);document.querySelectorAll('[data-partner-place]').forEach(pin=>pin.addEventListener('click',()=>{document.querySelectorAll('[data-partner-place]').forEach(item=>item.classList.remove('active'));pin.classList.add('active');document.getElementById('partner-map-label').textContent=pin.dataset.partnerPlace}));document.getElementById('partner-region')?.addEventListener('change',event=>notify(`Mapa atualizado para ${event.target.value}`));document.getElementById('partner-new')?.addEventListener('click',()=>notify('Cadastro e qualificação de novo parceiro iniciados'));document.getElementById('partner-docs')?.addEventListener('click',()=>notify('Biblioteca de documentos de expansão aberta'));document.querySelectorAll('[data-partner-review]').forEach(button=>button.addEventListener('click',()=>{const row=button.closest('tr');document.getElementById('partner-detail').innerHTML=`<section class="panel"><div class="section-head"><div><span class="eyebrow">Detalhes do parceiro</span><h2>${row.cells[0].textContent}</h2><p>${row.cells[1].textContent} · acompanhamento comercial e de impacto.</p></div><span class="badge">${row.cells[2].textContent}</span></div><div class="stat-grid compact"><article class="stat-card"><small>Pedidos/mês</small><strong>${row.cells[3].textContent}</strong></article><article class="stat-card"><small>Ticket médio</small><strong>R$ 198,40</strong></article><article class="stat-card"><small>NPS</small><strong>82</strong></article><article class="stat-card"><small>Tempo de resposta</small><strong>4h 15m</strong></article></div><div class="publish-actions"><button class="button secondary" id="partner-note">Registrar contato</button><button class="button primary" id="partner-advance">Avançar no funil</button></div></section>`;document.getElementById('partner-note').addEventListener('click',()=>notify('Contato registrado no histórico do parceiro'));document.getElementById('partner-advance').addEventListener('click',()=>{row.cells[2].innerHTML='<span class="badge">Em negociação</span>';notify('Parceiro avançou no funil de expansão')})}))}
function adminInnovation(){const experiments=[['Recomendação por IA','Aumentar conversão','Validação','+18% conversão'],['Gamificação sustentável','Aumentar engajamento','Validação','+25% retenção'],['Assinatura Flexível','Reduzir churn','Teste A/B','-15% churn'],['Embalagem retornável','Aumentar adesão','Teste A/B','+20% adesão'],['Checkout simplificado','Reduzir abandono','Teste A/B','-12% abandono']];const backlog=[['Sistema de Troca de Fraldas','9,2','Médio'],['Monitor de Impacto Ambiental','8,7','Alto'],['Parcerias com ONGs','8,5','Baixo'],['Reciclagem de Fraldas Usadas','8,1','Alto'],['API para Desenvolvedores','7,6','Médio']];return adminShell(`<div class="admin-toolbar"><div><span class="eyebrow">Experimentação orientada por valor</span><h2>Hub de inovação e portfólio de produtos</h2><p>Ideias, experimentos, testes com usuários, priorização e evolução contínua da plataforma.</p></div><button class="button primary" id="innovation-new">Nova ideia</button></div><div class="stat-grid"><article class="stat-card"><small>Usuários ativos em 30 dias</small><strong>1.842</strong><span>+24% no mês</span></article><article class="stat-card"><small>Ideias enviadas</small><strong>327</strong><span>+18% no mês</span></article><article class="stat-card"><small>Votos recebidos</small><strong>1.256</strong><span>+35% no mês</span></article><article class="stat-card"><small>NPS médio</small><strong>+42</strong><span>promotores</span></article></div><section class="panel"><div class="section-head"><div><h2>Funil de inovação</h2><p>Da descoberta à análise do impacto.</p></div><span class="badge">5 experimentos ativos · 2 em validação</span></div><div class="steps"><div class="step active"><div class="step-num">1</div><div><strong>Ideação</strong><p>Coleta da comunidade</p></div></div><div class="step active"><div class="step-num">2</div><div><strong>Seleção</strong><p>Impacto e viabilidade</p></div></div><div class="step active"><div class="step-num">3</div><div><strong>Experimentação</strong><p>Protótipos e testes</p></div></div><div class="step active"><div class="step-num">4</div><div><strong>Validação</strong><p>Hipóteses e ajustes</p></div></div><div class="step active"><div class="step-num">5</div><div><strong>Lançamento</strong><p>Publicação gradual</p></div></div><div class="step active"><div class="step-num">6</div><div><strong>Análise</strong><p>Adoção e impacto</p></div></div></div></section><section class="panel"><div class="section-head"><div><h2>Portfólio de novos produtos</h2><p>Iniciativas em desenvolvimento e planejamento.</p></div><select class="input" id="innovation-filter"><option value="">Todas as iniciativas</option><option>Em progresso</option><option>Planejado</option></select></div><div class="stat-grid"><article class="stat-card" data-innovation-card data-status="em progresso"><small>Assinatura Flex</small><strong>75%</strong><progress value="75" max="100"></progress><span>Em progresso</span></article><article class="stat-card" data-innovation-card data-status="em progresso"><small>Recompensas Verdes</small><strong>60%</strong><progress value="60" max="100"></progress><span>Em progresso</span></article><article class="stat-card" data-innovation-card data-status="em progresso"><small>IA de Recomendação</small><strong>50%</strong><progress value="50" max="100"></progress><span>Em progresso</span></article><article class="stat-card" data-innovation-card data-status="planejado"><small>Marketplace B2B</small><strong>30%</strong><progress value="30" max="100"></progress><span>Planejado</span></article></div></section><div class="dashboard-grid"><section class="panel"><div class="section-head"><div><h2>Testes com usuários</h2><p>Satisfação e facilidade de uso por rodada.</p></div><button class="button secondary" id="innovation-test">Registrar teste</button></div><div class="forecast-chart" aria-label="Evolução dos testes com usuários"><i style="height:48%"></i><i style="height:58%"></i><i style="height:55%"></i><i style="height:72%"></i><i style="height:84%"></i></div><div class="stat-grid compact"><article class="stat-card"><small>Testes nesta semana</small><strong>25</strong></article><article class="stat-card"><small>Satisfação</small><strong>4,6/5</strong></article><article class="stat-card"><small>Facilidade de uso</small><strong>88%</strong></article></div></section><section class="panel"><div class="section-head"><div><h2>Pesquisas e benchmarks</h2><p>Referências usadas na descoberta.</p></div></div><div class="phone-list"><article class="phone-card"><div><strong>E-commerce sustentável</strong><p>28% das referências</p></div><progress value="28" max="100"></progress></article><article class="phone-card"><div><strong>Logística reversa</strong><p>24%</p></div><progress value="24" max="100"></progress></article><article class="phone-card"><div><strong>Produtos reutilizáveis</strong><p>20%</p></div><progress value="20" max="100"></progress></article><article class="phone-card"><div><strong>Tecnologia e IA</strong><p>16%</p></div><progress value="16" max="100"></progress></article></div></section></div><section class="panel"><div class="section-head"><div><h2>Experimentos ativos</h2><p>Hipótese, estágio e impacto esperado.</p></div><button class="button text" id="innovation-export">Exportar relatório</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Experimento</th><th>Hipótese</th><th>Status</th><th>Impacto esperado</th><th>Ação</th></tr></thead><tbody>${experiments.map(row=>`<tr data-experiment-row>${row.map((cell,index)=>`<td>${index===2?`<span class="badge">${cell}</span>`:cell}</td>`).join('')}<td><button class="button text" data-experiment-review>Revisar</button></td></tr>`).join('')}</tbody></table></div></section><div class="dashboard-grid"><section class="panel"><div class="section-head"><div><h2>Roadmap de produtos</h2><p>Próximos três meses.</p></div></div><div class="phone-list"><article class="phone-card"><span class="badge">AGO</span><div><strong>Assinatura Flex</strong><p>Piloto e validação de recorrência.</p></div></article><article class="phone-card"><span class="badge">AGO–SET</span><div><strong>IA Recomendação 2.0</strong><p>Personalização e explicabilidade.</p></div></article><article class="phone-card"><span class="badge">SET</span><div><strong>Embalagem retornável</strong><p>Teste com parceiros regionais.</p></div></article><article class="phone-card"><span class="badge">OUT</span><div><strong>Aplicativo v2</strong><p>Evolução da experiência mobile.</p></div></article></div></section><section class="panel"><div class="section-head"><div><h2>Backlog de inovação</h2><p>Priorização por valor e esforço.</p></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Ideia</th><th>Pontuação</th><th>Esforço</th><th>Ação</th></tr></thead><tbody>${backlog.map(row=>`<tr data-backlog-row><td>${row[0]}</td><td><strong>${row[1]}</strong></td><td>${row[2]}</td><td><button class="button text" data-backlog-vote>Priorizar</button></td></tr>`).join('')}</tbody></table></div></section></div><div class="dashboard-grid"><section class="panel"><h2>Feedback dos usuários</h2><div class="notice"><strong>4,6/5</strong> com base em 312 avaliações.</div><div class="phone-list"><article class="phone-card"><span class="status-icon">✓</span><div><strong>Produtos de qualidade</strong><p>Elogio mais recorrente.</p></div></article><article class="phone-card"><span class="status-icon">✓</span><div><strong>Impacto ambiental positivo</strong><p>Propósito percebido pelos usuários.</p></div></article><article class="phone-card"><span class="status-icon">✓</span><div><strong>Entrega rápida e confiável</strong><p>Confiança no fluxo completo.</p></div></article></div></section><section class="panel"><h2>Adoção de novas funcionalidades</h2><div class="stat-card"><small>Usuários que adotaram</small><strong>58%</strong><progress value="58" max="100"></progress><span>32% pretendem usar · 7% ainda não conhecem · 3% sem interesse</span></div></section></div><div id="innovation-detail"></div>`,'innovation','Inovação e produtos')}
function setupAdminInnovation(){const add=document.getElementById('innovation-new');if(!add)return;add.addEventListener('click',()=>notify('Formulário de nova ideia aberto para a comunidade'));document.getElementById('innovation-filter')?.addEventListener('change',event=>{const term=event.target.value.toLowerCase();document.querySelectorAll('[data-innovation-card]').forEach(card=>card.hidden=Boolean(term)&&card.dataset.status!==term)});document.getElementById('innovation-test')?.addEventListener('click',()=>notify('Sessão de teste registrada com consentimento e evidências'));document.getElementById('innovation-export')?.addEventListener('click',()=>notify('Relatório de experimentos exportado'));document.querySelectorAll('[data-backlog-vote]').forEach(button=>button.addEventListener('click',()=>{button.textContent='Priorizado';button.disabled=true;notify('Ideia priorizada no backlog')}));document.querySelectorAll('[data-experiment-review]').forEach(button=>button.addEventListener('click',()=>{const row=button.closest('tr');document.getElementById('innovation-detail').innerHTML=`<section class="panel"><div class="section-head"><div><span class="eyebrow">Revisão do experimento</span><h2>${row.cells[0].textContent}</h2><p>${row.cells[1].textContent}</p></div><span class="badge">${row.cells[2].textContent}</span></div><div class="stat-grid compact"><article class="stat-card"><small>Amostra</small><strong>312</strong></article><article class="stat-card"><small>Confiança</small><strong>92%</strong></article><article class="stat-card"><small>Impacto esperado</small><strong>${row.cells[3].textContent}</strong></article><article class="stat-card"><small>Decisão</small><strong>Continuar</strong></article></div><div class="publish-actions"><button class="button secondary" id="experiment-pause">Pausar</button><button class="button primary" id="experiment-advance">Avançar estágio</button></div></section>`;document.getElementById('experiment-pause').addEventListener('click',()=>notify('Experimento pausado com justificativa registrada'));document.getElementById('experiment-advance').addEventListener('click',()=>{row.cells[2].innerHTML='<span class="badge">Validação</span>';notify('Experimento avançou para validação')})}))}
function adminLaunch(){const deliverables=['Plano de lançamento','Plano de suporte e SLA','Treinamentos e materiais','Comunicação e marketing','Migração de dados','Teste de carga final','Auditoria de segurança','Validação de aceite (UAT)','Deploy em produção','Monitoramento pós-deploy'];const channels=[['Central de Ajuda','help.fraldacycle.com.br'],['Chat online','Disponível no app e web'],['WhatsApp','(31) 99999-1234'],['E-mail','suporte@fraldacycle.com.br']];return adminShell(`<div class="admin-toolbar"><div><span class="eyebrow">Operação assistida e melhoria contínua</span><h2>Finalização, lançamento e suporte</h2><p>Go-live, saúde operacional, adesão, atendimento e evolução pós-lançamento em uma visão única.</p></div><div class="publish-actions"><button class="button secondary" id="launch-report">Relatório final</button><button class="button primary" id="launch-refresh">Atualizar operação</button></div></div><div class="stat-grid"><article class="stat-card"><small>Usuários ativos</small><strong>186</strong><span>1ª hora pós go-live</span></article><article class="stat-card"><small>Pedidos realizados</small><strong>42</strong><span>atividade real simulada</span></article><article class="stat-card"><small>Faturamento</small><strong>R$ 12.840,00</strong><span>natureza simulada</span></article><article class="stat-card"><small>Taxa de sucesso</small><strong>99,8%</strong><span>0 erros críticos</span></article><article class="stat-card"><small>Tempo de resposta</small><strong>215 ms</strong><span>dentro da meta</span></article></div><section class="panel"><div class="section-head"><div><h2>Checklist de lançamento</h2><p>Sete camadas validadas para o go-live.</p></div><span class="badge success">Lançamento bem-sucedido</span></div><div class="steps"><div class="step active"><div class="step-num">1</div><div><strong>Deploy</strong><p>Produção publicada</p></div></div><div class="step active"><div class="step-num">2</div><div><strong>Dados</strong><p>Migração validada</p></div></div><div class="step active"><div class="step-num">3</div><div><strong>Segurança</strong><p>Auditoria aprovada</p></div></div><div class="step active"><div class="step-num">4</div><div><strong>Comunicação</strong><p>Plano executado</p></div></div><div class="step active"><div class="step-num">5</div><div><strong>Treinamento</strong><p>Equipes preparadas</p></div></div><div class="step active"><div class="step-num">6</div><div><strong>Suporte</strong><p>Canais ativos</p></div></div><div class="step active"><div class="step-num">7</div><div><strong>Monitoramento</strong><p>Alertas 24/7</p></div></div></div></section><div class="dashboard-grid"><section class="panel"><div class="section-head"><div><h2>Entregas e prontidão</h2><p>Itens operacionais do lançamento.</p></div><select class="input" id="launch-delivery-filter"><option value="">Todos</option><option>Concluído</option><option>Monitorando</option></select></div><div class="phone-list">${deliverables.map((item,index)=>`<article class="phone-card" data-launch-delivery data-status="${index===9?'monitorando':'concluído'}"><span class="status-icon">${index===9?'◉':'✓'}</span><div><strong>${item}</strong><p>${index===9?'Monitorando':'Concluído'}</p></div><button class="button text" data-launch-evidence>Ver evidência</button></article>`).join('')}</div></section><section class="panel"><div class="section-head"><div><h2>Performance pós go-live</h2><p>Atividade por minuto na primeira hora.</p></div><span class="badge">Atualização automática</span></div><div class="forecast-chart" aria-label="Atividade por minuto"><i style="height:28%"></i><i style="height:42%"></i><i style="height:44%"></i><i style="height:58%"></i><i style="height:49%"></i><i style="height:70%"></i><i style="height:82%"></i><i style="height:55%"></i></div><div class="notice success-notice"><strong>Operação saudável.</strong> Banco de dados, APIs, integrações e segurança dentro das metas.</div></section></div><div class="dashboard-grid"><section class="panel"><div class="section-head"><div><h2>Canais de suporte ativos</h2><p>Atendimento integrado para famílias e parceiros.</p></div></div><div class="phone-list">${channels.map(row=>`<article class="phone-card"><span class="status-icon">✓</span><div><strong>${row[0]}</strong><p>${row[1]}</p></div><button class="button text" data-support-channel>Abrir</button></article>`).join('')}</div><div class="notice">Segunda a sexta: 8h–20h · sábado: 8h–14h.</div></section><section class="panel"><div class="section-head"><div><h2>Monitoramento e alertas</h2><p>Estado dos serviços essenciais.</p></div><button class="button secondary" id="launch-observability">Dashboard de observabilidade</button></div><div class="phone-list">${['Infraestrutura','Aplicação','Banco de dados','APIs e integrações','Segurança'].map(item=>`<article class="phone-card"><span class="status-dot online"></span><div><strong>${item}</strong><p>Saudável</p></div><span class="badge">Online</span></article>`).join('')}</div></section></div><div class="dashboard-grid"><section class="panel"><div class="section-head"><div><h2>Adesão inicial</h2><p>1.248 usuários cadastrados.</p></div></div><div class="phone-list"><article class="phone-card"><div><strong>Famílias</strong><p>65%</p></div><progress value="65" max="100"></progress></article><article class="phone-card"><div><strong>Instituições</strong><p>20%</p></div><progress value="20" max="100"></progress></article><article class="phone-card"><div><strong>Revendedores</strong><p>10%</p></div><progress value="10" max="100"></progress></article><article class="phone-card"><div><strong>Outros</strong><p>5%</p></div><progress value="5" max="100"></progress></article></div></section><section class="panel"><div class="section-head"><div><h2>Feedback inicial dos usuários</h2><p>NPS com base em 126 respostas.</p></div></div><div class="stat-card"><small>NPS</small><strong>72</strong><progress value="72" max="100"></progress><span>72% promotores · 20% neutros · 8% detratores</span></div><div class="phone-list"><article class="phone-card"><span class="status-icon">✓</span><div><strong>Plataforma intuitiva</strong><p>Fácil de usar e navegar.</p></div></article><article class="phone-card"><span class="status-icon">✓</span><div><strong>Compra rápida e segura</strong><p>Fluxo claro e confiável.</p></div></article><article class="phone-card"><span class="status-icon">✓</span><div><strong>Impacto positivo</strong><p>Propósito social e ambiental percebido.</p></div></article></div></section></div><div class="dashboard-grid"><section class="panel"><div class="section-head"><div><h2>Treinamentos realizados</h2><p>Preparação das pessoas que sustentam a operação.</p></div></div><div class="stat-grid compact"><article class="stat-card"><small>Equipe interna</small><strong>18</strong></article><article class="stat-card"><small>Usuários-chave</small><strong>24</strong></article><article class="stat-card"><small>Suporte e operações</small><strong>12</strong></article><article class="stat-card"><small>Parceiros e revendedores</small><strong>15</strong></article></div></section><section class="panel"><div class="section-head"><div><h2>Próximos passos pós-lançamento</h2><p>Plano operacional de evolução.</p></div></div><div class="phone-list"><article class="phone-card"><span class="status-icon">1</span><div><strong>Otimização contínua de performance</strong><p>Em andamento</p></div></article><article class="phone-card"><span class="status-icon">2</span><div><strong>Novas funcionalidades do backlog</strong><p>Agosto</p></div></article><article class="phone-card"><span class="status-icon">3</span><div><strong>Expansão de parcerias</strong><p>Agosto</p></div></article><article class="phone-card"><span class="status-icon">4</span><div><strong>Relatórios de impacto ESG</strong><p>Setembro</p></div></article></div></section></div><section class="panel"><div class="section-head"><div><h2>Indicadores de impacto projetado</h2><p>Projeção anual; não representa resultado realizado.</p></div></div><div class="stat-grid"><article class="stat-card"><small>Famílias impactadas</small><strong>25.000+</strong></article><article class="stat-card"><small>Resíduos evitados</small><strong>120 t</strong></article><article class="stat-card"><small>Emissões evitadas</small><strong>250 t CO₂e</strong></article><article class="stat-card"><small>Economia projetada</small><strong>R$ 4,2 mi</strong></article></div></section><div id="launch-detail"></div>`,'launch','Lançamento e suporte')}
function setupAdminLaunch(){const refresh=document.getElementById('launch-refresh');if(!refresh)return;refresh.addEventListener('click',()=>{refresh.disabled=true;refresh.innerHTML='<span class="inline-spinner dark"></span> Atualizando...';setTimeout(()=>{refresh.disabled=false;refresh.textContent='Operação atualizada';notify('Saúde operacional atualizada agora')},550)});document.getElementById('launch-report')?.addEventListener('click',()=>notify('Relatório final do projeto preparado'));document.getElementById('launch-delivery-filter')?.addEventListener('change',event=>{const term=event.target.value.toLowerCase();document.querySelectorAll('[data-launch-delivery]').forEach(card=>card.hidden=Boolean(term)&&card.dataset.status!==term)});document.querySelectorAll('[data-launch-evidence]').forEach(button=>button.addEventListener('click',()=>{const card=button.closest('[data-launch-delivery]');document.getElementById('launch-detail').innerHTML=`<section class="panel"><div class="section-head"><div><span class="eyebrow">Evidência operacional</span><h2>${card.querySelector('strong').textContent}</h2><p>Responsável, registro, data e resultado da validação.</p></div><span class="badge">${card.dataset.status}</span></div><div class="stat-grid compact"><article class="stat-card"><small>Responsável</small><strong>Operações</strong></article><article class="stat-card"><small>Validação</small><strong>Aprovada</strong></article><article class="stat-card"><small>Ambiente</small><strong>Produção</strong></article><article class="stat-card"><small>Registro</small><strong>#GO-015</strong></article></div></section>`}));document.querySelectorAll('[data-support-channel]').forEach(button=>button.addEventListener('click',()=>notify(`Canal aberto: ${button.closest('.phone-card').querySelector('strong').textContent}`)));document.getElementById('launch-observability')?.addEventListener('click',()=>{location.hash='#/admin/infrastructure'})}
function setupSiteImpact(){const period=document.getElementById('impact-period');if(!period)return;const factors={12:1,6:.58,1:.12,all:1.42};period.addEventListener('change',()=>{const factor=factors[period.value];document.querySelectorAll('[data-impact-value]').forEach(node=>{const value=Math.round(Number(node.dataset.impactValue)*factor);node.textContent=value.toLocaleString('pt-BR')+(node.dataset.unit||'')});notify('Indicadores atualizados para o período selecionado')});document.getElementById('impact-region').addEventListener('change',()=>notify('Recorte geográfico atualizado'));document.querySelectorAll('[data-impact-place]').forEach(pin=>pin.addEventListener('click',()=>{document.querySelectorAll('[data-impact-place]').forEach(item=>item.classList.remove('active'));pin.classList.add('active');document.getElementById('impact-map-label').textContent=pin.dataset.impactPlace}));document.getElementById('impact-export').addEventListener('click',()=>notify('Relatório de impacto exportado com fontes e metodologia'));document.getElementById('impact-methodology').addEventListener('click',()=>{document.getElementById('impact-methodology-panel')?.remove();const panel=document.createElement('section');panel.id='impact-methodology-panel';panel.className='panel impact-methodology-panel';panel.innerHTML='<div class="section-head"><div><span class="eyebrow">Rastreabilidade dos indicadores</span><h2>Metodologia, fontes e governança</h2><p>Cada indicador diferencia dado simulado, projetado e realizado.</p></div><button class="button text" id="impact-methodology-close">Fechar</button></div><div class="stat-grid compact"><article class="stat-card"><small>Fonte primária</small><strong>Data Warehouse</strong><span>transações e entregas consolidadas</span></article><article class="stat-card"><small>Atualização</small><strong>Diária · 06:00</strong><span>última carga identificada</span></article><article class="stat-card"><small>Conversão ambiental</small><strong>Fator versionado</strong><span>memória de cálculo auditável</span></article><article class="stat-card"><small>Privacidade</small><strong>Dados agregados</strong><span>sem identificação de famílias</span></article></div><div class="notice">Valores desta demonstração são simulados. Projeções anuais são explicitamente rotuladas e não representam resultados realizados.</div>';document.querySelector('.impact-dashboard .section-head')?.after(panel);document.getElementById('impact-methodology-close')?.addEventListener('click',()=>panel.remove());panel.scrollIntoView({behavior:'smooth',block:'start'})})}
